119	func inputSchemaForOperation(operation *openAPIOperation) jsonSchema {
120		properties := map[string]any{}
121		required := []string{}
122		defs := map[string]any{}
123		for _, parameter := range operation.Parameters {
124			schema := cloneSchema(parameter.Schema)
125			if parameter.Description != "" {
126				schema["description"] = parameter.Description
127			}
128			properties[parameter.Name] = schema
129			if parameter.Required {
130				required = append(required, parameter.Name)
131			}
132		}
133	
134		if operation.RequestBody != nil {
135			bodySchema := requestBodySchema(operation)
136			for name, definition := range extractSchemaDefs(bodySchema) {
137				defs[name] = definition
138			}
139			properties["body"] = bodySchema
140			if operation.RequestBody.Required {
141				required = append(required, "body")
142			}
143		}
144	
145		schema := jsonSchema{
146			"type":                 "object",
147			"properties":           properties,
148			"additionalProperties": false,
149		}
150		if len(required) > 0 {
151			schema["required"] = required
152		}
153		if len(defs) > 0 {
154			schema["$defs"] = defs
155		}
156		return schema
157	}
